/* -*- tab-width: 2 -*- */
'use strict';

function splitOnce(sepOrOpt, input) {
  let opt = (sepOrOpt || '');
  if (opt.length !== undefined) { opt = { sep: opt }; }
  const { sep } = opt;
  const sLen = (+(sep || false).length || 0);
  if (sLen <= 0) {
    const empty = input.slice(0, 0); /*
      By using .slice we don't need to check the type. */
    return (opt.last ? [input, empty] : [empty, input]);
  }
  let pos = (opt.last ? input.lastIndexOf(sep) : input.indexOf(sep));
  if (pos < 0) {
    pos = opt.notFound;
    if (!pos) { return false; }
    if (pos === 'orig') { return input; }
    if (pos === 'just0') { return [input]; }
    if (pos === 'empty0') { return [input.slice(0, 0), input]; }
    if (pos === 'empty1') { return [input, input.slice(0, 0)]; }
    throw new Error('Unsupported value for "notFound" option: ' + pos);
  }
  const head = input.slice(0, pos);
  const tail = input.slice(pos + sLen);
  return [head, tail];
}

splitOnce.last = function splitOnceLast(sep, input) {
  return splitOnce({ sep, last: true }, input);
};


module.exports = splitOnce;
